 bool region(uint32_t role,uint32_t u,uint32_t v,uint32_t sw,uint32_t sh,Rect r)const{auto*a=asset(role);if(!a||!a->sheet||!sw||!sh||u>a->width||v>a->height||sw>a->width-u||sh>a->height-v||r.z<0||r.w<0)return fail("PSI source texture region");if(r.z==0||r.w==0)return true;r.x=pixel(r.x);r.y=pixel(r.y);float x0=std::max(r.x,clip_.x),y0=std::max(r.y,clip_.y),x1=std::min(r.x+r.z,clip_.x+clip_.z),y1=std::min(r.y+r.w,clip_.y+clip_.w);if(x1<=x0||y1<=y0)return true;auto image=encore::ctr::loading_sprite_sheet_get_image(a->sheet,0);auto sub=*image.subtex;float du=(sub.right-sub.left)/a->width,dv=(sub.bottom-sub.top)/a->height,ox=sub.left,oy=sub.top;sub.left=ox+(u+(x0-r.x)*sw/r.z)*du;sub.right=ox+(u+(x1-r.x)*sw/r.z)*du;sub.top=oy+(v+(y0-r.y)*sh/r.w)*dv;sub.bottom=oy+(v+(y1-r.y)*sh/r.w)*dv;sub.width=uint16_t(pixel(x1-x0));sub.height=uint16_t(pixel(y1-y0));if(!sub.width||!sub.height)return true;return C2D_DrawImageAt({image.tex,&sub},pixel(x0),pixel(y0),0,nullptr,1,1)||fail("PSI GPU submit rejected");}
