 bool load(const Data&d,const FieldEquipmentRenderer*art,encore::upstream::ItemView items,const char*root,std::string&e){using B=encore::upstream::FieldBinding;std::string pin;for(auto byte:d.source_pin()){const char digits[]="0123456789abcdef";pin+=digits[byte>>4];pin+=digits[byte&15];}if(!d.valid()||!art||!art->ready()||!items.valid()||items.reviewed_commit()!=pin||!root||!*root||art->content().reviewed_commit()!=pin||art->content().binding(B::MainFont)!=d.source_font()||art->content().binding(B::NumberFont)!=d.number_font()){e="PSI checked font/art owners required";return false;}FieldPsiRenderer next;for(const auto&source:d.assets()){if(!source.file_bytes||!source.crc32){e="PSI source texture conversion receipt absent";return false;}std::string path=std::string(root)+source.path;std::ifstream f(path,std::ios::binary);if(!f){e="PSI GPU asset unavailable";return false;}f.seekg(0,std::ios::end);auto n=f.tellg();if(n!=source.file_bytes){e="PSI GPU asset size differs from source receipt";return false;}f.seekg(0);std::vector<uint8_t>b(static_cast<size_t>(n));if(!f.read(reinterpret_cast<char*>(b.data()),n)||crc(b)!=source.crc32){e="PSI GPU asset CRC rejected";return false;}Asset a;a.role=source.role;a.width=source.width;a.height=source.height;a.sheet=encore::ctr::loading_sprite_sheet_acquire(path.c_str(),&e);next.assets_.push_back(a);if(!a.sheet||encore::ctr::loading_sprite_sheet_count(a.sheet)!=1)return false;auto image=encore::ctr::loading_sprite_sheet_get_image(a.sheet,0);if(!image.tex||!image.subtex||Tex3DS_SubTextureRotated(image.subtex)||image.subtex->width!=source.width||image.subtex->height!=source.height){e="PSI GPU source texture dimensions";return false;}C3D_TexSetFilter(image.tex,GPU_NEAREST,GPU_NEAREST);}next.data_=&d;next.art_=art;next.items_=items;C3D_FrameSync();std::swap(data_,next.data_);std::swap(art_,next.art_);std::swap(items_,next.items_);assets_.swap(next.assets_);e.clear();return true;}
 // Exact borrowed font metrics are used by the menu's source 3/4-line decision.
